def parse_client(nombres, apellido_paterno, apellido_materno, contacto, direccion, edad=None) -> dict:
    errors = []
    rec = {
        "nombres_raw": nombres,
        "apellido_paterno_raw": apellido_paterno,
        "apellido_materno_raw": apellido_materno,
        "contacto_raw": contacto,
        "direccion_raw": direccion,
        "edad_raw": edad,
        "nombres": None,
        "apellido_paterno": None,
        "apellido_materno": None,
        "contacto": None,
        "direccion": None,
        "edad": None,
        "errors": errors,
    }
    requeridos = {
        "nombres": nombres,
        "apellido_paterno": apellido_paterno,
        "apellido_materno": apellido_materno,
        "contacto": contacto,
        "direccion": direccion,
    }
    for campo, valor in requeridos.items():
        limpio = valor.strip()
        if limpio == "":
            errors.append(f"ERROR en '{campo}': valor vacío (raw={valor!r})")
